import { runSession } from "./run-client.js";
/** An agent served over HTTP: the local eval server, a `--url`, or the playground host. */
export function localHttpEvalTransport(input) {
    return {
        send: (turn) => runSession({
            baseUrl: input.baseUrl,
            messages: [turn.message],
            sessionId: turn.sessionId,
            continuationToken: turn.continuationToken,
            startIndex: turn.startIndex,
            purpose: "eval",
            bearerToken: input.auth.bearerToken,
            headers: input.auth.headers,
            workspaceDir: turn.options.workspaceDir,
            workspaceFiles: turn.options.workspaceFiles,
            cloud: turn.options.cloud,
            timeoutMs: turn.timeoutMs,
            signal: turn.signal,
            onEvent: turn.onEvent,
        }),
    };
}
